#!/usr/bin/env python3
"""Generate src/py/entities.generated.ts from Python's html.entities.html5.

Run with the Python that is the reference (3.14): python3.14 tools/gen_entities.py
"""
import html.entities
import json
import os
import sys

html5 = html.entities.html5
# Names html.unescape may match without the ";" (the legacy ones): every key without it.
legacy = sorted(k for k in html5 if not k.endswith(";"))
full = sorted(k for k in html5 if k.endswith(";"))
out = [
    "// Generated by tools/gen_entities.py from Python %s html.entities.html5. Do not edit." % sys.version.split()[0],
    "// ENTITIES: every key of html5 (names with ';' and the legacy ones without), value = replacement text.",
    "// LEGACY_MAX: length of the longest legacy name (html.unescape tries prefixes up to this long).",
    "export const ENTITIES: Record<string, string> = {",
]
for k in sorted(html5):
    out.append("  %s: %s," % (json.dumps(k), json.dumps(html5[k], ensure_ascii=True)))
out.append("};")
out.append("export const LEGACY_MAX = %d;" % max(len(k) for k in legacy))
dest = os.path.join(os.path.dirname(os.path.abspath(__file__)), "..", "src", "py", "entities.generated.ts")
with open(dest, "w") as f:
    f.write("\n".join(out) + "\n")
print(len(html5), "entities,", len(legacy), "legacy")
